type NodeNameType = keyof typeof PlasmicDescendants;
type DescendantsType<T extends NodeNameType> =
  (typeof PlasmicDescendants)[T][number];
type NodeDefaultElementType = {
  root: "div";
  container: "div";
  menuBar: typeof MenuBar;
  content: "div";
  logo: typeof PlasmicImg__;
  authContainer: "div";
  playerButton: typeof Button;
  organizerButton: typeof Button;
  emailInput: typeof TextField;
  passwordInput: typeof TextField;
  rememberMeCheckbox: typeof Checkbox;
  forgetPasswordCheckbox: typeof Button;
  signInButton: typeof Button;
  signUpButton: typeof Button;
  googleButton: typeof Button;
  svg: "svg";
  signUpOption: "div";
  signUpSwitch: typeof Button;
  signInOption: "div";
  signInSwitch: typeof Button;
  debugDeleteAfterward: "div";
};

type ReservedPropsType = "variants" | "args" | "overrides";
type NodeOverridesType<T extends NodeNameType> = Pick<
  PlasmicAuthentication__OverridesType,
  DescendantsType<T>
>;
type NodeComponentProps<T extends NodeNameType> =
  // Explicitly specify variants, args, and overrides as objects
  {
    variants?: PlasmicAuthentication__VariantsArgs;
    args?: PlasmicAuthentication__ArgsType;
    overrides?: NodeOverridesType<T>;
  } &
    // Specify variants directly as props
    Omit<PlasmicAuthentication__VariantsArgs, ReservedPropsType> &
    // Specify args directly as props
    Omit<PlasmicAuthentication__ArgsType, ReservedPropsType> &
    // Specify overrides for each element directly as props
    Omit<
      NodeOverridesType<T>,
      ReservedPropsType | VariantPropType | ArgPropType
    > &
    // Specify props for the root element
    Omit<
      Partial<React.ComponentProps<NodeDefaultElementType[T]>>,
      ReservedPropsType | VariantPropType | ArgPropType | DescendantsType<T>
    >;

function makeNodeComponent<NodeName extends NodeNameType>(nodeName: NodeName) {
  type PropsType = NodeComponentProps<NodeName> & { key?: React.Key };
  const func = function <T extends PropsType>(
    props: T & StrictProps<T, PropsType>
  ) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicAuthentication__ArgProps,
          internalVariantPropNames: PlasmicAuthentication__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicAuthentication__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicAuthentication";
  } else {
    func.displayName = `PlasmicAuthentication.${nodeName}`;
  }
  return func;
}

